module serial2parallel (
    input clk, 
    input rst_n, 
    input din_serial, 
    input din_valid, 
    output reg [7:0] dout_parallel, 
    output reg dout_valid
);
// Sequential logic for serial to parallel conversion
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        dout_parallel <= 8'b0;
        dout_valid <= 1'b0;
    end else begin
        if (din_valid && !(&dout_parallel)) begin
            dout_parallel[dout_parallel[0]] <= din_serial;
            dout_parallel <= {1'b0, dout_parallel[7:1]};
            dout_valid <= 1'b0;
        end else if (&dout_parallel) begin
            dout_valid <= 1'b1;
        end else begin
            dout_valid <= 1'b0;
        end
    end
end
endmodule
